-- The 50 sample providers (src/server/directory/sample-data.ts), so a new
-- database shows a populated directory. Generated by scripts/sample-seed-sql.ts.
-- Skips anyone who already exists, and everything once an admin has removed
-- the samples (Admin → All providers).
-- Sara Oliisi
WITH guard AS (
  SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM "audit_log" WHERE "action" = 'samples.removed')
), u AS (
  INSERT INTO "user" ("id", "name", "email", "email_verified", "role", "first_name", "last_name")
  SELECT gen_random_uuid()::text, 'Sara Oliisi', 'sample-01@samples.psychmind.test', TRUE, 'provider', 'Sara', 'Oliisi' FROM guard
  ON CONFLICT ("email") DO NOTHING
  RETURNING "id"
), p AS (
  INSERT INTO "provider_profile" ("id", "user_id", "public_id", "status", "is_sample", "external_photo_url", "onboarding_step", "first_name", "last_name", "title_credentials", "pronouns", "banner_style", "who_you_work_with", "about", "session_participants", "age_groups", "specialties", "primary_specialty", "approaches", "languages", "gender", "fee_individual", "fee_couples", "sliding_scale", "accepting_new_clients", "education", "npi_number", "years_experience", "submitted_at", "approved_at")
  SELECT gen_random_uuid()::text, u."id", 'rnakdt7g', 'approved', TRUE, 'https://images.unsplash.com/photo-1734365294784-00255163b97d?auto=format&fit=crop&crop=faces&w=480&h=480&q=80', 'review', 'Sara', 'Oliisi', 'Counselor, LMHC, M.S., B.S.', 'she/her', 'banner_01', E'I primarily work with adults (18+) on an individual basis, though I also offer couples sessions. My clients often come to me when they feel like they''ve tried to manage things on their own and need a different kind of support — not advice, but a space to think more clearly.\n\nI work especially well with people who are skeptical about therapy, or who have tried it before and felt it wasn''t quite right. I take that seriously and we talk about it openly.', E'I work with adults who feel stuck, overwhelmed, or disconnected from the life they want to be living. Many of my clients are navigating anxiety, stress, relationship challenges, or questions about identity — and they''ve often been carrying these things alone for a long time before reaching out.\n\nMy approach is collaborative and paced to your comfort. I don''t believe therapy should feel like homework or a checklist. I believe it should feel like a conversation where you are genuinely heard — sometimes for the first time.', ARRAY['individuals', 'couples']::text[], ARRAY['adults']::text[], ARRAY['anxiety', 'relationships', 'self_esteem', 'life_transitions', 'cultural_identity', 'trauma_ptsd', 'grief_loss']::text[], 'anxiety', ARRAY['cbt', 'person_centered', 'narrative']::text[], ARRAY['French', 'English']::text[], 'female', 120, 160, FALSE, TRUE, '[{"degree":"Ph.D. Clinical Psychology","school":"Université Mohammed V, Rabat","year":2015}]'::jsonb, '1638423032', 9, now() - interval '4 days', now() - interval '2 days'
  FROM u
  RETURNING "id"
), l AS (
  INSERT INTO "provider_location" ("id", "profile_id", "state", "city", "zip", "practice_name", "address", "formats", "is_primary", "sort_order")
  SELECT gen_random_uuid()::text, p."id", v.state, v.city, v.zip, v.practice_name, v.address, v.formats, v.is_primary, v.sort_order
  FROM p, (VALUES
    ('FL', 'Miami', '33131', 'Brickell Counseling Studio', '1101 Brickell Ave, Suite 800', ARRAY['in_person', 'online']::text[], TRUE, 0)
  ) AS v(state, city, zip, practice_name, address, formats, is_primary, sort_order)
)
INSERT INTO "provider_license" ("id", "profile_id", "state", "license_number", "issuing_body", "status")
SELECT gen_random_uuid()::text, p."id", v.state, v.license_number, v.issuing_body, 'verified'
FROM p, (VALUES
    ('FL', 'LMHC-FL-98116', 'Florida Board of Clinical Social Work, Marriage & Family Therapy and Mental Health Counseling')
  ) AS v(state, license_number, issuing_body);
